operation.add:
// anchor-price-product-form-validation-v1
if (array_key_exists('anchor_price', $this->request->post) || array_key_exists('anchor_reference_date', $this->request->post)) {
	$this->load->language('extension/module/anchor_price');
	$this->load->model('extension/module/anchor_price');
	$anchor_price = $this->model_extension_module_anchor_price->normalisePrice(isset($this->request->post['anchor_price']) ? $this->request->post['anchor_price'] : '');
	$anchor_reference_date = $this->model_extension_module_anchor_price->normaliseDate(isset($this->request->post['anchor_reference_date']) ? $this->request->post['anchor_reference_date'] : '');

	if ($anchor_price === false || $anchor_reference_date === false || (($anchor_price === '') !== ($anchor_reference_date === ''))) {
		$this->error['anchor_price_pair'] = $this->language->get('error_anchor_price_pair');

		if (!isset($this->error['warning'])) {
			$this->error['warning'] = $this->error['anchor_price_pair'];
		}
	}
}

{# anchor-price-basel-product-card-v1 #}
